import { Component, Input, OnInit, OnDestroy, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormGroup, ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatNativeDateModule } from '@angular/material/core';
import { MatIconModule } from '@angular/material/icon';
import { MatSelectModule } from '@angular/material/select';
import { Subject, takeUntil } from 'rxjs';
import { ApiService } from '../../../core/services/api.service';
import { Temple } from '../../../core/models/temple.model';

@Component({
  selector: 'app-step-selection',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatDatepickerModule,
    MatNativeDateModule,
    MatIconModule,
    MatSelectModule
  ],
  templateUrl: './step-selection.html',
  styleUrl: './step-selection.scss',
})
export class StepSelectionComponent implements OnInit, OnDestroy {
  @Input({ required: true }) formGroup!: FormGroup;

  timeSlots: string[] = [];
  temples: Temple[] = [];
  defaultDuration = 5; // Fallback
  private destroy$ = new Subject<void>();
  private apiService = inject(ApiService);

  constructor() {
    this.generateTimeSlots();
  }

  ngOnInit() {
    // Fetch temples to get configuration
    this.apiService.get<Temple[]>('temples')
      .pipe(takeUntil(this.destroy$))
      .subscribe(temples => {
        this.temples = temples;
        // Update default duration if temple is already selected or default 'KATRA'
        this.updateDefaultDuration();
      });

    // Auto-calculate return date
    this.formGroup.get('date')?.valueChanges
      .pipe(takeUntil(this.destroy$))
      .subscribe(date => {
        if (date) {
          const startDate = new Date(date);
          const returnDate = new Date(startDate);
          returnDate.setDate(startDate.getDate() + this.defaultDuration);
          this.formGroup.get('returnDate')?.setValue(returnDate);
        }
      });

    // Also watch for templeId changes if it were dynamic
    this.formGroup.get('templeId')?.valueChanges
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => this.updateDefaultDuration());
  }

  updateDefaultDuration() {
    const templeId = this.formGroup.get('templeId')?.value || 'KATRA';
    const temple = this.temples.find(t => t.id === templeId);
    if (temple && temple.defaultDuration) {
      this.defaultDuration = temple.defaultDuration;

      // Re-trigger date calculation if date is already set
      const currentDate = this.formGroup.get('date')?.value;
      if (currentDate) {
        // We need to manually calculate again because setValue won't emit if it's the same, 
        // but here the logic depends on defaultDuration which changed.
        // Easier: reuse the same logic
        const startDate = new Date(currentDate);
        const returnDate = new Date(startDate);
        returnDate.setDate(startDate.getDate() + this.defaultDuration);
        this.formGroup.get('returnDate')?.setValue(returnDate);
      }
    }
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }

  generateTimeSlots() {
    for (let i = 0; i < 24; i++) {
      const hour = i < 10 ? `0${i}` : `${i}`;
      this.timeSlots.push(`${hour}:00`);
      this.timeSlots.push(`${hour}:30`);
    }
  }
}
