import { Component, Input, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { Store } from '@ngrx/store';
import { createBooking } from '../../../store/booking/booking.actions';
import { Booking } from '../../../core/models/booking.model';

@Component({
  selector: 'app-step-payment',
  standalone: true,
  imports: [CommonModule, MatButtonModule],
  templateUrl: './step-payment.html',
  styleUrl: './step-payment.scss',
})
export class StepPaymentComponent {
  @Input({ required: true }) selection!: any;
  @Input({ required: true }) facilities!: any;
  @Input({ required: true }) pilgrims!: any;

  private store = inject(Store);

  confirmPayment() {
    const booking: Booking = {
      templeId: this.selection.templeId,
      userId: 'test-user-id', // Mock user ID
      date: this.selection.date,
      facilities: [], // Map from checks
      pilgrims: this.pilgrims.pilgrims,
      totalAmount: 1000, // Mock amount
      status: 'pending'
    };
    if (this.facilities.accommodation) booking.facilities.push('accommodation');
    if (this.facilities.transport) booking.facilities.push('transport');

    this.store.dispatch(createBooking({ booking }));
  }
}
