import { Component, Input, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormArray, FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatSelectModule } from '@angular/material/select';

@Component({
  selector: 'app-step-pilgrims',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, MatFormFieldModule, MatInputModule, MatButtonModule, MatIconModule, MatSelectModule],
  templateUrl: './step-pilgrims.html',
  styleUrl: './step-pilgrims.scss',
})
export class StepPilgrimsComponent {
  @Input({ required: true }) formGroup!: FormGroup;
  private fb = inject(FormBuilder);

  get pilgrims(): FormArray {
    return this.formGroup.get('pilgrims') as FormArray;
  }

  addPilgrim() {
    this.pilgrims.push(this.fb.group({
      id: [crypto.randomUUID()],
      name: ['', Validators.required],
      age: ['', [Validators.required, Validators.min(1)]],
      gender: ['', Validators.required]
    }));
  }

  removePilgrim(index: number) {
    this.pilgrims.removeAt(index);
  }
}
