import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatStepperModule } from '@angular/material/stepper';
import { MatButtonModule } from '@angular/material/button';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { StepSelectionComponent } from '../step-selection/step-selection';
import { StepFacilitiesComponent } from '../step-facilities/step-facilities';
import { StepPilgrimsComponent } from '../step-pilgrims/step-pilgrims';
import { StepPaymentComponent } from '../step-payment/step-payment';

@Component({
  selector: 'app-booking-wizard',
  standalone: true,
  imports: [
    CommonModule,
    MatStepperModule,
    MatButtonModule,
    ReactiveFormsModule,
    StepSelectionComponent,
    StepFacilitiesComponent,
    StepPilgrimsComponent,
    StepPaymentComponent
  ],
  templateUrl: './booking-wizard.html',
  styleUrl: './booking-wizard.scss',
})
export class BookingWizardComponent {
  private _formBuilder = inject(FormBuilder);

  selectionFormGroup = this._formBuilder.group({
    templeId: ['KATRA', Validators.required], // Default to KATRA
    date: ['', Validators.required],
    time: ['10:00', Validators.required],
    returnDate: [''],
    returnTime: ['18:00']
  });
  facilitiesFormGroup = this._formBuilder.group({
    accommodation: [false],
    transport: [false],
  });
  pilgrimsFormGroup = this._formBuilder.group({
    pilgrims: this._formBuilder.array([]),
  });
}
