import { Component, Input, OnChanges, SimpleChanges, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, FormControl } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { MatRadioModule } from '@angular/material/radio';
import { MatCardModule } from '@angular/material/card';
import { MatButtonModule } from '@angular/material/button';
import { MatExpansionModule } from '@angular/material/expansion';
import { MatIconModule } from '@angular/material/icon';
import * as L from 'leaflet';

interface RouteLeg {
  id: string;
  name: string;
  from: string;
  to: string;
  transportOptions: string[]; // e.g., ['eRickshaw', 'Walk/Self', 'Pony']
  coordinates: [number, number][]; // Simple polyline approximation
}

@Component({
  selector: 'app-step-facilities',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatCheckboxModule,
    MatSelectModule,
    MatRadioModule,
    MatCardModule,
    MatButtonModule,
    MatExpansionModule,
    MatIconModule
  ],
  templateUrl: './step-facilities.html',
  styleUrls: ['./step-facilities.scss'],
})
export class StepFacilitiesComponent implements OnChanges {
  @Input({ required: true }) formGroup!: FormGroup;
  @Input() pilgrims: any[] = []; // List of pilgrims from previous step

  private fb = inject(FormBuilder);
  map: L.Map | undefined;
  routeLayer: L.Polyline | undefined;

  // Define Route Legs
  legs: RouteLeg[] = [
    {
      id: 'leg1',
      name: 'Katra to Ardhakumari',
      from: 'Katra',
      to: 'Ardhakumari',
      transportOptions: ['Walk/Self', 'Auto/Rickshaw', 'Pony', 'Palki'],
      coordinates: [[32.9922, 74.9390], [33.0125, 74.9480]]
    },
    {
      id: 'leg2',
      name: 'Ardhakumari to Bhawan',
      from: 'Ardhakumari',
      to: 'Bhawan',
      transportOptions: ['Walk/Self', 'Battery Car', 'Ropeway', 'Pony'],
      coordinates: [[33.0125, 74.9480], [33.0308, 74.9490]]
    },
    {
      id: 'leg3',
      name: 'Bhawan to Sanjhi Chhat',
      from: 'Bhawan',
      to: 'Sanjhi Chhat',
      transportOptions: ['Walk/Self', 'Pony', 'Helicopter (Return)'],
      coordinates: [[33.0308, 74.9490], [33.0250, 74.9420]]
    },
    {
      id: 'leg4',
      name: 'Sanjhi Chhat to Ardhakumari',
      from: 'Sanjhi Chhat',
      to: 'Ardhakumari',
      transportOptions: ['Walk/Self', 'Pony'],
      coordinates: [[33.0250, 74.9420], [33.0125, 74.9480]]
    },
    {
      id: 'leg5',
      name: 'Ardhakumari to Katra',
      from: 'Ardhakumari',
      to: 'Katra',
      transportOptions: ['Walk/Self', 'Pony', 'Palki'],
      coordinates: [[33.0125, 74.9480], [32.9922, 74.9390]]
    }
  ];

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['pilgrims'] && this.pilgrims.length > 0) {
      this.initFormControls();
    }
  }

  initFormControls() {
    // We need to build a form structure:
    // routes: {
    //   leg1: { pilgrimId1: 'Walk', pilgrimId2: 'Pony' },
    //   leg2: { ... }
    // }

    // Check if controls already exist to avoid resetting on every change if not needed
    if (!this.formGroup.get('routes')) {
      const routesGroup = this.fb.group({});

      this.legs.forEach(leg => {
        const legGroup = this.fb.group({});
        // Add "Via Bhairavbaba" control for Leg 3
        if (leg.id === 'leg3') {
          legGroup.addControl('viaBhairav', new FormControl(false));
        }

        this.pilgrims.forEach(p => {
          legGroup.addControl(p.id, new FormControl('Walk/Self')); // Default
        });

        routesGroup.addControl(leg.id, legGroup);
      });

      this.formGroup.addControl('routes', routesGroup);
    } else {
      // If pilgrims changed (added/removed), we might need to update existing groups
      // For simplicity, strict "OnChanges" usually means previous step completed.
    }
  }

  // Map Logic
  ngAfterViewInit() {
    this.initMap();
  }

  initMap() {
    this.map = L.map('facilities-map').setView([33.0125, 74.9450], 13);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(this.map);

    // Initially show Leg 1
    this.highlightLeg(this.legs[0]);
  }

  highlightLeg(leg: RouteLeg) {
    if (!this.map) return;
    this.map.invalidateSize();

    if (this.routeLayer) {
      this.map.removeLayer(this.routeLayer);
    }

    this.routeLayer = L.polyline(leg.coordinates, { color: 'blue', weight: 5 }).addTo(this.map);
    this.map.fitBounds(this.routeLayer.getBounds(), { padding: [50, 50] });
  }
}
